contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint waitTime) public payable {
        require(amount <= address(this).balance);

        // Setup: advance c's pastBlockTime to a nonzero value so that we have
        // a meaningful lower bound for the timestamp check in the fallback.
        // The setup call must satisfy the fallback's own preconditions: 10 ether
        // and timestamp > current pastBlockTime (which starts at 0, so any
        // nonzero timestamp works). The test contract must own the 10 ether.
        c.fallback{value: 10 ether}();

        uint setupTime = c.pastBlockTime();

        // Bound the amount and wait so that the timestamp condition is meaningful
        // and no over/underflow can occur in the assertion below.
        amount = amount % (11 ether) + 9 ether; // amounts in [9 ether, 20 ether); 10 ether included
        waitTime = waitTime % (2 ** 32);        // bounded increment

        // Record the timestamp before the deciding call. If no time has passed,
        // the fallback must revert. If time has passed and amount == 10 ether,
        // it must succeed; otherwise it must revert.
        uint beforeTimestamp = block.timestamp;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool timeAdvanced = beforeTimestamp > setupTime;
        bool correctAmount = (amount == 10 ether);
        bool shouldSucceed = timeAdvanced && correctAmount && (beforeTimestamp > c.pastBlockTime());

        if (shouldSucceed) {
            assert(!reverted);
        } else {
            assert(reverted);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
