    }

    function run(uint amount, uint waitTime) public payable {
        require(address(this).balance >= amount, "insufficient balance");

        // Setup: make one successful fallback call so pastBlockTime becomes nonzero.
        c.call{value: 10 ether}("");
        uint setupTime = c.pastBlockTime();

        // Bound parameters so the deciding call can be analyzed safely.
        amount = amount % (11 ether) + 9 ether; // [9 ether, 20 ether), includes 10 ether
        waitTime = waitTime % (2 ** 32);        // bounded number of seconds

        // Advance time by warp-equivalent: use waitTime as a guaranteed lower bound
        // on block.timestamp progression between setup and deciding call.
        uint beforeTimestamp = block.timestamp + waitTime;

        bool reverted;
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool enoughTime = beforeTimestamp > setupTime;
        bool exactAmount = (amount == 10 ether);
        bool shouldSucceed = enoughTime && exactAmount;

        if (shouldSucceed) {
            assert(!reverted);
        } else {
            assert(reverted);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint firstAmount) public payable {
        require(address(this).balance >= amount + firstAmount, "insufficient balance");
        require(firstAmount == 10 ether, "first call must be exact amount");

        // First fallback call with exactly 10 ether should succeed (fresh contract, pastBlockTime = 0).
        bool firstReverted;
        (bool ok1, ) = address(c).call{value: firstAmount}("");
        firstReverted = !ok1;
        uint afterFirst = c.pastBlockTime();

        // Second deciding call through fallback, same transaction/timestamp.
        bool reverted;
        (bool ok2, ) = address(c).call{value: amount}("");
        reverted = !ok2;

        // General rule: first exact-amount call succeeds; second call reverts
        // because timestamp is not strictly greater than pastBlockTime
        // unless amount is not exactly 10 ether, which also reverts.
        assert(!firstReverted && (reverted || amount != 10 ether ? reverted : reverted));
    }

    receive() external payable {}
}

