contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint tsBefore) public payable {
        require(tsBefore > 0 && tsBefore < block.timestamp, "precondition: need a past timestamp");

        // Bring the contract into a known pastBlockTime state if possible.
        if (amount == 10 ether) {
            c.pastBlockTime();
            if (c.pastBlockTime() == 0) {
                c.fallback{value: amount}();
            }
        }

        bool reverted;
        if (amount == 10 ether) {
            try c.fallback{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.fallback{value: amount > 10 ether ? amount : amount + 1}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        if (amount == 10 ether) {
            assert(!reverted && c.pastBlockTime() == block.timestamp);
        } else {
            assert(reverted);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
