    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint tsBefore) public payable {
        require(tsBefore > 0 && tsBefore < block.timestamp, "precondition: need a past timestamp");
        require(address(this).balance >= amount, "insufficient balance");

        // Bring the contract into a state with pastBlockTime strictly less than current block.timestamp.
        if (c.pastBlockTime() >= block.timestamp) {
            return;
        }
        if (c.pastBlockTime() == 0) {
            c.fallback{value: 10 ether}();
            if (c.pastBlockTime() >= block.timestamp) {
                return;
            }
        }

        bool reverted;
        if (amount == 10 ether) {
            try c.fallback{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(!reverted && c.pastBlockTime() == block.timestamp);
        } else {
            try c.fallback{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
        }
    }

    receive() external payable {}
}

