contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 value, uint256 timestamp) public payable {
        require(value == 10 ether);
        require(address(this).balance >= value);
        require(timestamp > block.timestamp);

        uint256 beforeTime = c.pastBlockTime();

        uint256 balanceBefore = address(c).balance;
        uint256 thisBalanceBefore = address(this).balance;

        uint256 oldTimestamp = block.timestamp;
        vm.warp(timestamp);

        bool reverted;
        try c.call{value: value}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = address(c).balance;
        uint256 thisBalanceAfter = address(this).balance;

        if (reverted) {
            assert(c.pastBlockTime() == beforeTime);
            assert(balanceAfter == balanceBefore);
            assert(thisBalanceAfter == thisBalanceBefore);
        } else {
            assert(c.pastBlockTime() == timestamp);
            assert(balanceAfter == balanceBefore + value || balanceAfter == 0);
            assert(thisBalanceAfter == thisBalanceBefore - value);
            assert(timestamp > beforeTime);
        }

        vm.warp(oldTimestamp);
    }
}

