contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 t1, uint256 t2) public payable {
        require(address(this).balance >= amount);

        // A call with value not equal to 10 ether must always revert,
        // independent of timestamp state.
        bool wrongValueReverted;
        try c.call{value: amount}("") {
            wrongValueReverted = false;
        } catch {
            wrongValueReverted = true;
        }

        require(wrongValueReverted);

        // Set a known timestamp baseline t1 (t1 == 0 is a legal initial timestamp).
        bool firstOk;
        try c.call{value: 10 ether}("") {
            firstOk = true;
        } catch {
            firstOk = false;
        }

        require(!firstOk);
        require(c.pastBlockTime() == t1);

        // With baseline t1 fixed, a call sending exactly 10 ether is accepted
        // iff its timestamp t2 is strictly greater than t1.
        uint256 balanceBefore = address(this).balance;

        bool secondOk;
        try c.call{value: 10 ether}("") {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        bool expectedOk = t2 > t1;
        uint256 observedPast = c.pastBlockTime();
        uint256 expectedPast = expectedOk ? t2 : t1;
        uint256 expectedBalance = expectedOk ? balanceBefore - 10 ether : balanceBefore;

        assert(
            secondOk == expectedOk &&
            observedPast == expectedPast &&
            address(this).balance == expectedBalance
        );
    }

    receive() external payable {}
}

