contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 tsBefore) public payable {
        require(amount == 10 ether);
        require(tsBefore > 0);
        require(address(this).balance >= amount);

        // Advance past the stored timestamp using a timestamp that is either valid or stale.
        // We cannot control block.timestamp directly, so we read the contract's current
        // pastBlockTime and use the provided tsBefore as a lower bound.
        uint256 past = c.pastBlockTime();
        require(past >= tsBefore);

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // On success the stored timestamp must have been updated to the current block timestamp.
            assert(c.pastBlockTime() == block.timestamp);
        } else {
            // If it reverted, it must be because block.timestamp was not greater than the stored timestamp.
            assert(block.timestamp <= past);
        }
    }

    receive() external payable {}
}

