            reverted = false;
        } catch {
            reverted = true;
        }

        uint postPastBlockTime = c.pastBlockTime();
        uint postContractBalance = address(c).balance;

        if (expectRevert) {
            assert(reverted);
        } else {
            assert(!reverted);
            assert(postPastBlockTime == timestamp);
            if (block.number % 15 == 0) {
                assert(postContractBalance == 0);
            } else {
                assert(postContractBalance == preContractBalance + amount);
            }
        }
    }

    receive() external payable {}
}

