            // the prior timestamp (it must advance to the actual block.timestamp, which
            // will be >= newTimestamp if our supplied timestamp was a lower bound
            // represented by the input; the input here is a marker, not the chain time).
            assert(amount == 10 ether);
            assert(c.pastBlockTime() >= beforeTime);
        }

        // General invariant: the call reverted iff it did not send exactly 10 ether
        // or the supplied timestamp did not exceed the stored one.
        assert(reverted == !expectSuccess);
    }

    receive() external payable {}
}

