contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint targetTime) public payable {
        require(address(this).balance >= amount);

        // Ensure c has some balance so the fallback's final transfer branch can be meaningful.
        (bool seedOk, ) = address(c).call{value: amount}("");
        require(seedOk);
        // The seed call records pastBlockTime; we assume it succeeded.

        // If targetTime is in the future relative to current block.timestamp, we cannot
        // necessarily make pastBlockTime less than it due to timestamp monotonicity.
        // We only assert about the success path when the contract did not revert.
        uint prev = c.pastBlockTime();
        require(targetTime > block.timestamp);

        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: a successful fallback call updates pastBlockTime to a value strictly
        // greater than the previous pastBlockTime. A revert preserves the previous value.
        assert(
            (!reverted && c.pastBlockTime() > prev) ||
            (reverted && c.pastBlockTime() == prev)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint8 which) public payable {
        require(address(this).balance >= 10 ether);

        // Seed the contract with a first fallback call to establish a pastBlockTime,
        // only if the chosen branch is to perform the main deciding call.
        // which == 0: expect success (timestamp already greater than pastBlockTime);
        // which == 1: expect revert (timestamp not greater than pastBlockTime).

        uint prev = c.pastBlockTime();

        bool reverted;
        if (which == 0) {
            // Force pastBlockTime to be less than current block.timestamp by ensuring
            // a seed call succeeds first (block.timestamp is always > 0 at deployment).
            if (prev == 0) {
                // First call: block.timestamp is definitely > 0, so this should succeed.
                try c.fallback{value: 10 ether}() {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            } else {
                // Already seeded; to guarantee timestamp > pastBlockTime we need
                // block.timestamp to be strictly greater, which cannot be forced.
                // Use a different tactic: skip by directly calling and asserting on the outcome.
                try c.fallback{value: 10 ether}() {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            }
        } else {
            // which == 1: we want a revert because block.timestamp <= pastBlockTime.
            // This is only guaranteed if pastBlockTime >= block.timestamp. Since we cannot
            // set pastBlockTime arbitrarily, we can only test this when prev >= block.timestamp,
            // which may not hold. Instead, we perform the deciding call and assert the general
            // invariant regardless of revert status.
            try c.fallback{value: 10 ether}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // General rule: if the call succeeded, block.timestamp must have been strictly
        // greater than the previous pastBlockTime, and pastBlockTime must have increased.
        // If it reverted, pastBlockTime must be unchanged.
        assert(
            (!reverted && block.timestamp > prev && c.pastBlockTime() > prev) ||
            (reverted && c.pastBlockTime() == prev)
        );
    }

    receive() external payable {}
}

