        // We'll require that the timestamp condition holds so that we test the success branch.
        // For a rule that covers both branches, we can test both, but we want exactly one assert.
        // The rule we assert will be: if the call succeeds, then value == 10 ether and timestamp > beforeTime.
        // We'll drive the call with the given value and observe if it reverts.

        // Make the deciding call: send `value` wei to the fallback.
        bool callReverted;
        try c.call{value: value}("") {
            callReverted = false;
        } catch {
            callReverted = true;
        }

        // Read after-state.
        uint256 afterTime = c.pastBlockTime();

        // General rule: the fallback succeeds iff exactly 10 ether was sent AND the timestamp condition was met at call time.
        // Since we cannot directly capture the timestamp at the moment of the call, we note that the call succeeds
        // only if value == 10 ether. The timestamp condition is a necessary condition for success, but we cannot
        // observe whether it was true because the call would revert otherwise. However, we can state the contrapositive:
        // If the call succeeds, then value == 10 ether AND afterTime > beforeTime (since pastBlockTime is updated to
        // the call timestamp, which must have been > beforeTime). Also, if value != 10 ether, the call must revert.
        // This is a general rule over all inputs.
        assert(
            (!callReverted && value == 10 ether && afterTime > beforeTime) ||
            (callReverted && (value != 10 ether || afterTime != beforeTime))
        );
    }

    receive() external payable {}
}

